-- Importa el Maestro de precios de TERRAC (4 catalogos). Pegar TODO y Run.
-- Si ya se importo antes, frena y no duplica nada.
DO $imp$
DECLARE v_org uuid; v_cat uuid; n int;
BEGIN
  SELECT count(DISTINCT org_id) INTO n FROM (SELECT org_id FROM budgets UNION SELECT org_id FROM price_catalogs) o;
  IF n <> 1 THEN RAISE EXCEPTION 'Hay % organizaciones en la base: pedile a Claude el SQL con el org_id', n; END IF;
  SELECT org_id INTO v_org FROM (SELECT org_id FROM budgets UNION SELECT org_id FROM price_catalogs) o LIMIT 1;
  IF EXISTS (SELECT 1 FROM price_catalogs WHERE name LIKE 'Maestro TERRAC - %') THEN
    RAISE EXCEPTION 'El Maestro ya estaba importado: no se cargo nada de nuevo';
  END IF;
  WITH ins AS (
    RETURNING id, org_id, precio_sin_iva, fecha_precio
  )
  SELECT id, org_id, precio_sin_iva, fecha_precio FROM ins WHERE precio_sin_iva IS NOT NULL;
  WITH ins AS (
    RETURNING id, org_id, precio_sin_iva, fecha_precio
  )
  SELECT id, org_id, precio_sin_iva, fecha_precio FROM ins WHERE precio_sin_iva IS NOT NULL;
  WITH ins AS (
    RETURNING id, org_id, precio_sin_iva, fecha_precio
  )
  SELECT id, org_id, precio_sin_iva, fecha_precio FROM ins WHERE precio_sin_iva IS NOT NULL;
  WITH ins AS (
    RETURNING id, org_id, precio_sin_iva, fecha_precio
  )
  SELECT id, org_id, precio_sin_iva, fecha_precio FROM ins WHERE precio_sin_iva IS NOT NULL;
END
$imp$;

-- Resultado: tiene que mostrar 4 catalogos
SELECT c.name AS catalogo, count(e.id) AS entradas, count(e.fecha_precio) AS con_fecha
FROM price_catalogs c JOIN catalog_entries e ON e.catalog_id = c.id
WHERE c.name LIKE 'Maestro TERRAC - %' GROUP BY c.name ORDER BY c.name;
